11	/**
12	 * The module's one translation of OGame relationship state into a theory-of-mind read.
13	 *
14	 * PsychSim answers a single cooperate/defect stance from a defection incentive; the module owns
15	 * the mapping (threat scales into that incentive) and the typed result, so every consumer —
16	 * social exchanges, alliance and buddy admission, the conversation reply and the campaign
17	 * brief — reads the same wary account instead of re-deriving it.
18	 */
19	class PsychSimTheoryOfMind
20	{
21	    /** The counterparty's payoff for defecting on a cooperator, on the sidecar's 0..2 scale. */
22	    private const DEFECTION_INCENTIVE_SCALE = 2.0;
23	
24	    /**
25	     * The account's depth-one read of a counterparty it rates at this threat (0..1).
26	     *
27	     * Threat doubles into the sidecar's 0..2 incentive, so the model cooperates below half and
28	     * defects above it: an account reads a more-than-half-threatening counterparty as someone
29	     * who will exploit it. Null means the driver had no answer and the caller keeps its native
30	     * stance.
31	     */
32	    public function stanceFor(float $threat): AiToMStance|null
33	    {
34	        // A driver that is not the selected cognition engine is never contacted: the account
35	        // keeps its native stance, and an unselected sidecar costs nothing and answers nothing.
36	        // The client is resolved here, not injected, so an unselected driver costs no wiring.
37	        if (!$this->enabled()) {
38	            return null;
39	        }
40	
41	        $decision = app(PsychSimClient::class)->decide($threat * self::DEFECTION_INCENTIVE_SCALE);
42	
43	        return $decision === null ? null : AiToMStance::from($decision);
44	    }
45	
46	    /**
47	     * The account's read of a specific counterparty, from the relationship the module recorded.
48	     * Null means there is no recorded relationship (or no driver read), so the caller keeps its
49	     * native decision.
50	     */
51	    public function stanceToward(int $playerId, int $otherPlayerId): AiToMStance|null
52	    {
53	        $threat = AiRelationship::query()
54	            ->where('player_id', $playerId)
55	            ->where('other_player_id', $otherPlayerId)
56	            ->value('threat');
57	
58	        return $threat === null ? null : $this->stanceFor((float) $threat);
59	    }
60	
61	    private function enabled(): bool
62	    {
63	        return AiCognitionMode::tryFrom((string) config('ai.cognition.mode', AiCognitionMode::External->value)) !== AiCognitionMode::Native
